<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='invoice'){ $pdo->beginTransaction();$no='INV-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$qty=max(1,(float)$_POST['quantity']);$price=max(0,(float)$_POST['unit_price']);$discount=max(0,(float)$_POST['discount']);$subtotal=$qty*$price;$total=max(0,$subtotal-$discount);$s=$pdo->prepare('INSERT INTO invoices(patient_id,invoice_no,subtotal,discount,total) VALUES(?,?,?,?,?)');$s->execute([(int)$_POST['patient_id'],$no,$subtotal,$discount,$total]);$iid=(int)$pdo->lastInsertId();$s=$pdo->prepare('INSERT INTO invoice_items(invoice_id,description,quantity,unit_price,total) VALUES(?,?,?,?,?)');$s->execute([$iid,trim($_POST['description']),$qty,$price,$total]);$pdo->commit();audit('create','invoice',$iid,$no);flash('Invoice created: '.$no);redirect('billing.php');}elseif($action==='payment'){ $iid=(int)$_POST['invoice_id'];$amt=(float)$_POST['amount'];if($amt>0){$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO payments(invoice_id,amount,method,reference) VALUES(?,?,?,?)');$s->execute([$iid,$amt,$_POST['method'],trim($_POST['reference']??'')]);$paid=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments WHERE invoice_id='.$iid)->fetchColumn();$total=(float)$pdo->query('SELECT total FROM invoices WHERE id='.$iid)->fetchColumn();$status=$paid+0.001>=$total?'Paid':($paid>0?'Part-paid':'Unpaid');$pdo->prepare('UPDATE invoices SET status=? WHERE id=?')->execute([$status,$iid]);$pdo->commit();audit('payment','invoice',$iid,'UGX '.$amt);flash('Payment recorded.');}redirect('billing.php');}}
$patients=$pdo->query('SELECT id,patient_no,full_name FROM patients ORDER BY full_name')->fetchAll();$rows=$pdo->query('SELECT i.*,p.patient_no,p.full_name,COALESCE((SELECT SUM(amount) FROM payments py WHERE py.invoice_id=i.id),0) paid FROM invoices i JOIN patients p ON p.id=i.patient_id ORDER BY i.created_at DESC LIMIT 150')->fetchAll();admin_header('Billing','billing.php');?><div class="pagehead"><div><h1>Billing & Payments</h1><div class="muted">Create invoices and record payments in UGX or your accounting workflow.</div></div><a class="btn" href="?action=new">Create invoice</a></div><?php if(($_GET['action']??'')==='new'):?><div class="card" style="margin-bottom:18px"><h2>New invoice</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="invoice"><div class="form-grid"><div class="field"><label>Patient</label><select name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>" <?=((int)($_GET['patient_id']??0)==$p['id']?'selected':'')?>><?=e($p['patient_no'].' — '.$p['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Description</label><input name="description" required placeholder="Consultation / procedure / medicine"></div><div class="field"><label>Quantity</label><input type="number" step="0.01" name="quantity" value="1" min="0.01"></div><div class="field"><label>Unit price (UGX)</label><input type="number" step="0.01" name="unit_price" min="0" required></div><div class="field"><label>Discount (UGX)</label><input type="number" step="0.01" name="discount" value="0" min="0"></div></div><button style="margin-top:14px">Create invoice</button></form></div><?php endif;?><div class="card table-wrap"><table class="table"><tr><th>Invoice</th><th>Patient</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th>Record payment</th></tr><?php foreach($rows as $r):$bal=max(0,(float)$r['total']-(float)$r['paid']);?><tr><td><?=e($r['invoice_no'])?></td><td><?=e($r['patient_no'].' — '.$r['full_name'])?></td><td>UGX <?=number_format((float)$r['total'],0)?></td><td>UGX <?=number_format((float)$r['paid'],0)?></td><td>UGX <?=number_format($bal,0)?></td><td><?=e($r['status'])?></td><td><?php if($bal>0):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="payment"><input type="hidden" name="invoice_id" value="<?=$r['id']?>"><input type="number" step="0.01" name="amount" value="<?=$bal?>" max="<?=$bal?>" min="0.01"><select name="method"><option>Cash</option><option>Mobile Money</option><option>Bank</option><option>Insurance</option><option>Other</option></select><input name="reference" placeholder="Reference"><button>Save</button></form><?php else:?><span class="badge ok">Fully paid</span><?php endif;?></td></tr><?php endforeach;?></table></div><?php admin_footer();
